async function setLigand(id){if(!S.meta?.ligands.some(l=>l.id===id))throw new Error('Unknown ligand');return loadLigand(id);}
async function setState(state){if(!['raw','relaxed','paired'].includes(state))throw new Error('Unknown coordinate state');S.state=state;return loadLigand(loadPending?.id||S.ligand);}
async function setMetric(metric){if(!['contacts','rmsd','selected_atoms','heme'].includes(metric))throw new Error('Unknown metric');S.metric=metric;$('metric').value=metric;paintAtoms();return analyze();}
function setColor(metric){if(!['method','cluster',...R.metrics.map(m=>m.id),...(S.meta?.metrics.filter(m=>m.kind==='score').map(m=>m.id)||[])].includes(metric))throw new Error('No fixed percentile normalization for this color metric');S.color=metric;$('color').value=metric;if(S.data){S.background=[];$('groupStatus').textContent='Loading receptor background…';}render();syncViewer();if(S.data)loadGroup();}
async function refresh(){cancel();const ticket=requests.bootstrap.start();message('Loading snapshot…');try{const filters=readFilters();const response=await fetch('/articles/admet-cyp-structure/cofolding/api/bootstrap',{cache:'no-store',signal:ticket.signal});if(!response.ok)throw new Error('Snapshot bootstrap '+response.status);const next=await response.json();if(!requests.bootstrap.current(ticket))return;requests.load.cancel();requests.group.cancel();discardAnalysis();session=Object.freeze(next);contactsSession=Object.freeze({...next,source_snapshot:next.scientific_source?.snapshot||next.source_snapshot});clearData();const[meta,versions]=await Promise.all([json('/api/meta',{signal:ticket.signal}),json('/api/versions',{signal:ticket.signal})]);if(!requests.bootstrap.current(ticket))return;session=Object.freeze({...session,analysis_source_snapshot:next.source_snapshot});initMeta({...meta,projection_version:versions.projection});for(const[id,value]of Object.entries(filters)){if($(id).type==='checkbox')$(id).checked=value;else $(id).value=value;}await loadLigand(S.ligand||S.meta.default_ligand);}catch(e){error(e);}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=H.element(document,'a',undefined,{href:url,download:name});a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportState(){flushFilters();download('pose-view.json',JSON.stringify({...stateCopy(),poses:(S.selected.size?(S.data?.poses||[]).filter(p=>S.selected.has(p.id)):tableRows)},null,2),'application/json');}
function cancel(){discardGroup();discardLoad();discardAnalysis();Object.values(requests).forEach(r=>r.cancel());busy(false);message('Request cancelled');}
function bind(){
 const scroller=$('poseTable').parentElement;scroller.addEventListener('scroll',()=>{if(!tableFrame)tableFrame=requestAnimationFrame(()=>{tableFrame=0;drawTableWindow();});},{passive:true});new ResizeObserver(()=>drawTableWindow()).observe(scroller);
 $('ligand').onchange=()=>setLigand($('ligand').value).catch(error);$('state').onchange=()=>setState($('state').value).catch(error);$('metric').onchange=()=>setMetric($('metric').value).catch(error);$('color').onchange=()=>setColor($('color').value);$('cluster').onchange=()=>selectCluster($('cluster').value);$('moiety').onchange=()=>{const m=S.data?.moieties.find(x=>String(x.id)===$('moiety').value);if(m){setAtoms(m.atoms);$('moiety').value=m.id;}};$('clearAtoms').onclick=()=>setAtoms([]);$('analyze').onclick=analyze;$('threshold').addEventListener('input',()=>analyze());$('cancel').onclick=cancel;$('refresh').onclick=refresh;$('clearSelection').onclick=()=>selectMany([]);$('addCluster').onclick=()=>addBulk('cluster');$('addMethod').onclick=()=>addBulk('method');$('cancelViewer').onclick=()=>{viewer?.cancel();S.overlays=new Set(viewer?[...viewer.roots.keys()]:[]);render();syncViewer();message('Bulk load cancelled · loaded poses retained');};$('addOverlay').onclick=()=>{const id=$('overlaySelect').value;if(!S.overlays.has(id))toggleOverlay(id);};$('fitViewer').onclick=$('resetCamera').onclick=()=>viewer?.fit();for(const id of ['showLigand','showHeme','showProtein','showPocket','lockCamera','showSubmitted','showRevealed'])$(id).onchange=syncViewer;
 for(const id of ['search','minPercentile','maxStrain','maxInteraction'])$(id).addEventListener('input',scheduleFilters);for(const id of ['cohort','selectedOnly','availableOnly','filterMetric','ser119Contact','arg105Contact'])$(id).addEventListener('change',()=>{scheduleFilters.cancel();render();});$('clearFilters').onclick=()=>{scheduleFilters.cancel();for(const id of ['cohort','search','filterMetric','minPercentile','maxStrain','maxInteraction','ser119Contact','arg105Contact'])$(id).value='';$('selectedOnly').checked=$('availableOnly').checked=false;S.clusterFilter='';$('cluster').value='';S.methods=new Set(S.meta.methods.map(m=>m.id));$('methods').querySelectorAll('input').forEach(e=>e.checked=true);render();};
 $('similarGroup').onchange=()=>{S.similar=new Set([...$('similarGroup').querySelectorAll('input:checked')].map(x=>x.value));loadGroup();};
 $('applyGroup').onclick=()=>{S.similar=new Set([...$('similarGroup').querySelectorAll('input:checked')].map(x=>x.value));loadGroup();clearMenus();};
 $('exportVisibleCSV').onclick=()=>{flushFilters();download('filtered-poses.csv',H.csv(tableRows.map(p=>exportRecord(p))),'text/csv');};$('exportCSV').onclick=()=>{flushFilters();const rows=(S.data?.poses||[]).filter(p=>S.selected.has(p.id)).map(p=>exportRecord(p));if(!rows.length){message('No selected rows');return;}download('selected-poses.csv',H.csv(rows),'text/csv');};$('exportJSON').onclick=exportState;document.querySelectorAll('[data-png]').forEach(b=>b.onclick=async()=>{flushFilters();try{await settlePlot(b.dataset.png);await Plotly.downloadImage($(b.dataset.png),{format:'png',filename:b.dataset.png,width:1600,height:1200,scale:2});}catch(e){error(e);}});$('exportViewer').onclick=async()=>{try{const uri=await viewer?.screenshot();if(!uri)throw new Error('Viewer image export unavailable');const a=H.element(document,'a',undefined,{href:uri,download:'pose-structures.png'});a.click();}catch(e){error(e);}};
 $('provenanceButton').onclick=()=>{provenance();$('provenance').hidden=false;};$('closeProvenance').onclick=()=>{$('provenance').hidden=true;};
 for(const[key,label]of columnDefinitions){const row=H.element(document,'label'),box=H.element(document,'input',undefined,{type:'checkbox'});box.checked=S.columns.has(key);box.onchange=()=>{flushFilters();box.checked?S.columns.add(key):S.columns.delete(key);render('table');};row.append(box,document.createTextNode(label));$('columns').append(row);}
 document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)clearMenus(d);}));document.addEventListener('click',e=>{if(!e.target.closest('details'))clearMenus();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){cancel();selectMany([]);clearMenus();$('provenance').hidden=true;document.querySelectorAll('.expanded').forEach(p=>p.classList.remove('expanded'));resize();}if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();$('search').closest('details').open=true;$('search').focus();}});
 document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{$(b.dataset.expand).closest('.panel').classList.toggle('expanded');resize();});
 const handle=$('tableResize');handle.onpointerdown=e=>{handle.setPointerCapture(e.pointerId);};handle.onpointermove=e=>{if(handle.hasPointerCapture(e.pointerId)){const bottom=$('workspace').getBoundingClientRect().bottom;document.documentElement.style.setProperty('--table-height',Math.max(90,Math.min(innerHeight*.65,bottom-e.clientY))+'px');resize();}};handle.onpointerup=e=>handle.releasePointerCapture(e.pointerId);handle.onkeydown=e=>{if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const h=document.querySelector('.table-panel').getBoundingClientRect().height;document.documentElement.style.setProperty('--table-height',Math.max(90,Math.min(innerHeight*.65,h+(e.key==='ArrowUp'?20:-20)))+'px');resize();}};
 new ResizeObserver(resize).observe($('workspace'));
}
let resizeFrame=0;function resize(){cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{for(const id of ['posePlot','receptorPlot','energyPlot'])if($(id)._fullLayout)Plotly.Plots.resize($(id));viewer?.instance?.handleResize();});}
Object.defineProperty(window,'poseExplorer',{value:Object.freeze({get state(){return stateCopy();},getState:stateCopy,get tableIDs(){return tableRows.map(p=>p.id);},selectPose,selectCluster,setLigand,setState,setMetric,setColor,setAtoms,analyze,refresh,cancel,get viewer(){return viewer?.instance;},get viewerDiagnostics(){return viewer?.diagnostics;},get plots(){return JSON.parse(JSON.stringify(S.plotIds));}}),writable:false});
function contactStatus(status){let node=$('contactStatus');if(!node){node=H.element(document,'span','',{id:'contactStatus',role:'status'});$('message').after(node);}node.replaceChildren();if(status.state==='loading')node.textContent='H-bonds loading · values Unknown';else if(status.state==='failed'){node.textContent='H-bonds unavailable · values Unknown · ';const retry=H.element(document,'button','Retry H-bonds');retry.onclick=()=>loadContacts(S.ligand);node.append(retry);node.title=status.error||'';}if(S.data&&status.ligand===S.ligand&&status.revision===session?.snapshot){render();syncViewer();}}
function loadContacts(id){const expected=session;R.load(contactsSession,id).catch(e=>{if(e.name!=='AbortError'&&session===expected&&S.ligand===id)contactStatus(R.status);});}
async function start(){bind();R.subscribe(contactStatus);render();viewer=new PoseViewer('viewer',$('viewerStatus'));const viewerReady=viewer.init().then(()=>syncViewer()).catch(error);try{await refresh();}catch(e){error(e);$('coverage').textContent='API unavailable';}await viewerReady;}
start();
